package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextUniversalFamilyInspection.*;
import org.kanger.ContextUniversalUnitProof.Proof;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** Three-variable producers retain a universally quantified coordinate through family barriers. */
final class ContextAuthorityPartial {
    static int checks;static final int WORK=64000000;
    static void require(boolean yes,String why){++checks;if(!yes)throw new AssertionError(why);}
    static ContextUniversalCandidate.Evaluation inspect(ContextSevenPremiseNativeWriteRunner.Fixture f,String text,int rounds)throws Exception{return f.db.qualifyUniversalProductionCandidate(f.root,text,1000,rounds,16,16,65536,1000000,WORK,500000,WORK);}
    static final class Coordinates {
        final SemanticTermSnapshot x,y,z;final List<SemanticTermSnapshot> q,mid;
        Coordinates(ContextProductionCandidate.Staged a,ContextAuthorityChain.Expected e,boolean conflict){Map<String,SemanticTermSnapshot> values=new HashMap<>();for(Entry entry:a.base.primary){Atom atom=entry.clauses.get(0).literals.get(0);values.put(atom.predicate,atom.arguments.get(0).value);}x=values.get("p1");y=values.get("p2");Atom deny=a.foreign.stream().flatMap(c->c.primary.stream()).filter(row->row.source.equals(e.deny)).findFirst().get().clauses.get(0).literals.get(0);z=deny.arguments.get(0).value;require(x!=null&&y!=null&&z!=null&&!x.semanticallyEquals(y)&&!x.semanticallyEquals(z)&&!y.semanticallyEquals(z),"three distinct actual semantic values");require(deny.arguments.size()==3&&deny.arguments.get(1).value.semanticallyEquals(conflict?x:y)&&deny.arguments.get(2).value.semanticallyEquals(conflict?y:x),"matching or incompatible fixed coordinates in deny");q=Arrays.asList(x,y,z);mid=Arrays.asList(z,x,y);}
    }
    static boolean ground(Atom atom,List<SemanticTermSnapshot> target){if(atom.arguments.size()!=target.size())return false;for(int i=0;i<target.size();i++)if(atom.arguments.get(i).variable>=0||!atom.arguments.get(i).value.semanticallyEquals(target.get(i)))return false;return true;}
    static void units(ContextUniversalUnitRounds.Frontier f,String predicate,int depth,List<Set<Source>> expected,Coordinates c,boolean negative,boolean ground){Set<Set<Source>> actual=new HashSet<>();int count=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1){Atom atom=row.clause.literals.get(0);if(!atom.predicate.equals(predicate))continue;++count;require(atom.positive!=negative&&atom.arguments.size()==3&&row.support.depth==depth&&actual.add(row.support.sources),"exact polarity, ternary arity, whole support and cumulative depth");if(ground)require(row.clause.variables.isEmpty()&&ground(atom,c.q),"ground counterproduction substitutes the formerly free coordinate");else{int free=predicate.equals("out")?2:0;require(row.clause.variables.size()==1&&atom.arguments.get(free).variable>=0,"one universal coordinate survives partial substitution");int xi=predicate.equals("out")?0:1,yi=predicate.equals("out")?1:2;require(atom.arguments.get(xi).variable<0&&atom.arguments.get(yi).variable<0&&atom.arguments.get(xi).value.semanticallyEquals(c.x)&&atom.arguments.get(yi).value.semanticallyEquals(c.y),"fixed coordinates retain their order around the free coordinate");}}require(count==expected.size()&&actual.equals(new HashSet<>(expected)),"all exact partial-unit source alternatives for "+predicate);}
    static void consistent(Result r,ContextAuthorityChain.Expected e,Coordinates value){require(r.status==Status.CONSISTENT&&r.collision==null&&r.certificate!=null&&r.completedBarriers>=2,"nonmatching ground deny has a complete stable-family model");ContextUniversalFamilyModel.Certificate c=r.certificate;require(c.cuts.size()==7&&c.input.cuts.size()==7,"seven exact private cuts");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut cut:c.cuts){receipts.add(cut.receipt);models.add(cut.model);require(cut.receipt.verified&&cut.receipt.input==c.input&&cut.model.ledger==cut.receipt.closureStep.input,"model is bound to its exact private closure");}require(ContextUniversalFamilyModel.certify(c.input,receipts,models,16,65536,WORK).certified,"independent all-values certificate recheck");List<Set<Source>> out=new ArrayList<>(),mid=new ArrayList<>();for(Source donor:e.authorities){out.add(e.set(donor));for(Source bridge:e.bridges)mid.add(e.set(donor,bridge));}units(c.input,"out",3,out,value,e.negativeOut,false);units(c.input,"mid",4,mid,value,e.negative,false);require(c.input.products.stream().filter(row->row.clause.literals.size()==1).count()==9,"exactly nine partial units; no raw donor import");}
    static void collision(Result r,ContextAuthorityChain.Expected e,Coordinates value,boolean exactLocal){require(r.status==Status.COLLISION&&r.certificate==null&&r.completedBarriers==3&&r.collision.oppositions.size()==12,"twelve complete third-barrier oppositions");Map<Set<Source>,Set<String>> actual=new HashMap<>();Set<Set<Source>> expected=e.pairs();for(Proof p:r.collision.oppositions){require(p.contradiction&&p.dependsOnX&&p.conclusion==null&&p.support.depth==5&&p.left.literals.size()==1&&p.right.literals.size()==1,"whole sourced unit refutation at cumulative depth5");Atom l=p.left.literals.get(0),rr=p.right.literals.get(0);require(l.predicate.equals(rr.predicate)&&l.positive!=rr.positive,"opposite signed endpoint");if(l.predicate.equals("q")){Set<Integer> slots=new HashSet<>();for(Slot slot:l.arguments){require(slot.variable>=0,"original private donor remains universal");slots.add(slot.variable);}require(slots.size()==3&&l.positive!=e.negativeQ&&p.leftSupport.sources.stream().anyMatch(e.authorities::contains)&&ground(rr,value.q),"ground counter-q instantiates all three independent donor slots");}else require(l.predicate.equals("mid")&&ground(l,value.mid)&&l.positive==e.negative&&p.leftSupport.sources.contains(e.deny)&&rr.arguments.size()==3&&rr.arguments.get(0).variable>=0&&rr.arguments.get(1).value.semanticallyEquals(value.x)&&rr.arguments.get(2).value.semanticallyEquals(value.y),"ground deny meets universally free first mid coordinate");require(p.leftSupport.depth==0&&p.leftSupport.sources.size()==1&&p.rightSupport.depth==4&&p.rightSupport.sources.size()==5,"private origin against transported whole five-source support");Set<Source> local=new HashSet<>(),foreign=new HashSet<>();for(Source source:p.support.sources)(source.localX?local:foreign).add(source);Set<Source> pair=new HashSet<>(foreign);pair.remove(e.deny);require(p.support.sources.size()==6&&local.size()==3&&foreign.size()==3&&foreign.contains(e.deny)&&expected.contains(pair),"whole X plus exact donor, Bridge and Deny");if(exactLocal)require(local.equals(e.locals),"exact fresh local Sources");require(actual.computeIfAbsent(pair,k->new HashSet<>()).add(l.predicate),"no duplicate endpoint hides another route");}require(actual.keySet().equals(expected)&&actual.values().stream().allMatch(v->v.equals(new HashSet<>(Arrays.asList("q","mid")))),"all six independently enumerated source pairs at both endpoints");}
    static void barriers(ContextProductionCandidate.Staged a,ContextAuthorityChain.Expected e,Coordinates value,boolean conflict){ContextUniversalUnitRounds.Frontier initial=ContextUniversalUnitRounds.start(a.staged,a.foreign,WORK);ContextUniversalUnitRounds.Barrier first=ContextUniversalUnitRounds.merge(initial,ContextUniversalAuthorityChain.pass(initial,16),16,WORK);require(first.status==ContextUniversalUnitRounds.Status.MERGED&&first.changed&&initial.products.isEmpty(),"immutable first barrier");List<Set<Source>> out=new ArrayList<>(),mid=new ArrayList<>(),counter=new ArrayList<>();for(Source donor:e.authorities){out.add(e.set(donor));for(Source bridge:e.bridges)mid.add(e.set(donor,bridge));}for(Source bridge:e.bridges)counter.add(e.set(bridge,e.deny));units(first.frontier,"out",3,out,value,e.negativeOut,false);int saved=first.frontier.products.size();require(first.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==3,"first barrier exports three partial out schemas");ContextUniversalUnitRounds.Barrier second=ContextUniversalUnitRounds.merge(first.frontier,ContextUniversalAuthorityChain.pass(first.frontier,16),16,WORK);require(second.status==ContextUniversalUnitRounds.Status.MERGED&&second.changed&&first.frontier.products.size()==saved,"immutable second barrier");units(second.frontier,"out",3,out,value,e.negativeOut,false);units(second.frontier,"mid",4,mid,value,e.negative,false);if(conflict)units(second.frontier,"q",4,counter,value,!e.negativeQ,true);require(second.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==(conflict?11:9),"exact second-barrier units");}
    static void caseOf(Path dir,String name,boolean reverse,boolean negative,boolean conflict,boolean nativePath,String text)throws Exception{
        Set<String> persisted;List<RevisionRef> pins;long settled;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,name)){
            require(f.root.compile("!~p1(1); !~p2(2);",null,false),"two exact local premise assertions");List<String> names=new ArrayList<>(Arrays.asList("A1","A2","A3","Bridge1","Bridge2","Deny"));if(reverse)Collections.reverse(names);for(String target:names)f.db.connectContext(target);f.db.saveConnections(f.root);
            ContextProductionInventory baseline=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> initial=ContextSevenPremiseNativeWriteRunner.origins(baseline);pins=ContextSevenPremiseNativeWriteRunner.pins(f);long revision=f.db.getRevision();int rows=f.root.getRules().size();require(initial.size()==2&&pins.size()==6,"only two local primary facts and six saved pins");
            ContextUniversalCandidate.Evaluation diagnostic=inspect(f,text,16);require(diagnostic.status==(conflict?Status.COLLISION:Status.CONSISTENT),"exact partial-substitution verdict: "+diagnostic.reason);
            ContextAuthorityChain.Expected expected=new ContextAuthorityChain.Expected(diagnostic.artifact,2,negative,negative,negative,false);
            Coordinates value=new Coordinates(diagnostic.artifact,expected,conflict);
            Clause candidate=diagnostic.artifact.staged.primary.stream().filter(e->e.source.equals(diagnostic.artifact.candidate)).findFirst().get().clauses.get(0);
            require(candidate.variables.size()==3&&candidate.literals.size()==4,"whole candidate retains three independent variables and four literals");
            Map<String,Atom> atoms=new HashMap<>();for(Atom atom:candidate.literals)atoms.put(atom.predicate,atom);
            Atom q=atoms.get("q"),out=atoms.get("out");require(q.arguments.size()==3&&out.arguments.size()==3,"ternary endpoints");
            Set<Integer> variables=new HashSet<>();for(int i=0;i<3;i++){require(q.arguments.get(i).variable>=0&&q.arguments.get(i).variable==out.arguments.get(i).variable,"candidate coordinate identity");variables.add(q.arguments.get(i).variable);}require(variables.size()==3&&atoms.get("p1").arguments.get(0).variable==q.arguments.get(0).variable&&atoms.get("p2").arguments.get(0).variable==q.arguments.get(1).variable,"independent x/y premises leave z free");
            for(org.kanger.ContextProductionNativeBinding.Snapshot cut:diagnostic.artifact.foreign)for(Entry entry:cut.primary){Clause c=entry.clauses.get(0);if(expected.authorities.contains(entry.source)){Atom atom=c.literals.get(0);Set<Integer> slots=new HashSet<>();for(Slot slot:atom.arguments){require(slot.variable>=0,"universal private donor coordinate");slots.add(slot.variable);}require(c.variables.size()==3&&slots.size()==3,"three independent private donor coordinates");}if(expected.bridges.contains(entry.source)){Atom o=c.literals.stream().filter(l->l.predicate.equals("out")).findFirst().get(),m=c.literals.stream().filter(l->l.predicate.equals("mid")).findFirst().get();require(c.variables.size()==3&&o.arguments.size()==3&&m.arguments.size()==3&&m.arguments.get(0).variable==o.arguments.get(2).variable&&m.arguments.get(1).variable==o.arguments.get(0).variable&&m.arguments.get(2).variable==o.arguments.get(1).variable,"private Bridge preserves exact cyclic permutation");}}
            if(conflict)collision(diagnostic.qualification,expected,value,true);else consistent(diagnostic.qualification,expected,value);
            barriers(diagnostic.artifact,expected,value,conflict);
            ContextUniversalCandidate.Evaluation bounded=f.db.qualifyUniversalProductionCandidate(f.root,text,1000,16,16,16,20000,1000000,WORK,500000,WORK);
            if(conflict){require(bounded.status==Status.COLLISION,"conflict reaches its proof before exhausting the smaller instance budget");ContextAuthorityChain.Expected small=new ContextAuthorityChain.Expected(bounded.artifact,2,negative,negative,negative,false);collision(bounded.qualification,small,new Coordinates(bounded.artifact,small,true),true);}else require(bounded.status==Status.INCOMPLETE&&bounded.qualification.certificate==null&&bounded.qualification.collision==null&&bounded.reason.contains("Universal quotient instance limit"),"previous fixture instance allowance refuses without a partial verdict");
            ContextUniversalCandidate.Evaluation stopped=inspect(f,text,1);require(stopped.status==Status.INCOMPLETE&&stopped.qualification.certificate==null&&stopped.qualification.collision==null&&stopped.reason.contains("common round limit"),"one common round cannot certify or expose opposition prefix");
            require(f.db.getRevision()==revision&&f.root.getRules().size()==rows&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(baseline.fingerprint)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"diagnostics preserve exact physical parent and topology");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(text,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(conflict){require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified,"actual native conflict independently audited");require(failure.getFamilyAudit().verdict!=diagnostic.qualification,"native guard uses a fresh actual-child verdict");collision(failure.getFamilyAudit().verdict,expected,value,false);}else require(failure==null,"actual native consistent candidate accepted");}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,text,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(conflict?DB.ProductionWriteStatus.COLLISION:DB.ProductionWriteStatus.PUBLISHED),"fresh public writer reaches expected settlement: "+result.status+" / "+result.trial.reason);require(result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"historical diagnostic is not publication authority");require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"exact pretrial and physical settlement references");if(conflict){ContextAuthorityChain.Expected fresh=new ContextAuthorityChain.Expected(result.trial.artifact,2,negative,negative,negative,false);collision(result.trial.qualification,fresh,new Coordinates(result.trial.artifact,fresh,conflict),true);}else{require(result.audit.oppositions.isEmpty(),"consistent publication has no collision attribution");ContextAuthorityChain.Expected fresh=new ContextAuthorityChain.Expected(result.trial.artifact,2,negative,negative,negative,false);consistent(result.trial.qualification,fresh,new Coordinates(result.trial.artifact,fresh,conflict) );}}
            ContextProductionInventory current=ContextSevenPremiseNativeWriteRunner.inventory(f);persisted=ContextSevenPremiseNativeWriteRunner.origins(current);settled=f.db.getRevision();require(ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"publication/refusal retains exact pinned order");
            if(conflict)require(settled==revision&&f.root.getRules().size()==rows&&current.fingerprint.equals(baseline.fingerprint)&&persisted.equals(initial),"conflict refusal retains exact original physical theory");
            else{require(settled>revision&&current.primary.size()==3&&persisted.size()==3&&persisted.containsAll(initial),"only one new whole rule is durably published");ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(f.root,current,WORK,500000);require(bound.bound&&bound.snapshot.primary.size()==3&&bound.snapshot.primary.stream().anyMatch(e->e.clauses.size()==1&&e.clauses.get(0).equivalent(candidate)),"actual published primary equals the requested universal candidate");require(bound.snapshot.primary.stream().allMatch(e->e.clauses.size()==1&&(e.clauses.get(0).equivalent(candidate)||(e.clauses.get(0).literals.size()==1&&!e.clauses.get(0).literals.get(0).positive&&(e.clauses.get(0).literals.get(0).predicate.equals("p1")||e.clauses.get(0).literals.get(0).predicate.equals("p2"))))),"only original premises and whole candidate, no private or derived primary import");}
            System.out.println("PARTIAL conflict="+conflict+" negative="+negative+" reverse="+reverse+" native="+nativePath+" diagnosticBarriers="+diagnostic.qualification.completedBarriers+" primary="+current.primary.size());
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,name)){ContextProductionInventory inv=ContextSevenPremiseNativeWriteRunner.inventory(f);require(f.db.getRevision()>=settled&&inv.primary.size()==(conflict?2:3)&&ContextSevenPremiseNativeWriteRunner.origins(inv).equals(persisted)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"reopen retains exactly original premises plus optional candidate and all pins");}
    }
    static void run(boolean reverse,boolean negative,boolean conflict,String marker){try{Path dir=Files.createTempDirectory("authority-partial-");System.setProperty("user.home",dir.toString());String sign=negative?"~":"";for(String name:new String[]{"A1","A2","A3"})ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"q(x,y,z);");for(String name:new String[]{"Bridge1","Bridge2"})ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"out(x,y,z)->"+sign+"mid(z,x,y);");ContextAuthorityChain.create(dir,"Deny","!"+(negative?"":"~")+(conflict?"mid(9,1,2);":"mid(9,2,1);"));String text="!@x @y @z "+sign+"q(x,y,z)&&~p1(x)&&~p2(y)->"+sign+"out(x,y,z);";caseOf(dir,"Public",reverse,negative,conflict,false,text);caseOf(dir,"Native",reverse,negative,conflict,true,text);System.out.println(marker+" checks="+(checks+ContextAuthorityChain.checks));System.exit(0);}catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
}
